package com.pritimitra.backend.messaging;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

/** Conversation and message DTOs. Never expose internal ids, sender account references, or Cognito subjects. */
public final class ConversationDtos {

	private ConversationDtos() {
	}

	/** Client send request. {@code clientMessageId} is generated by the client and reused on every retry. */
	public record SendMessageRequest(UUID clientMessageId, String body) {
	}

	/**
	 * A stored message. {@code clientMessageId} is returned only for the viewer's own messages so a retry can be
	 * matched to its original send.
	 */
	public record MessageSummary(UUID messageId, UUID clientMessageId, String body, boolean mine, Instant createdAt) {
	}

	/** Newest-first page of history. {@code nextCursor} points to older messages and is null when none remain. */
	public record MessagePage(List<MessageSummary> items, String nextCursor) {
	}

	/**
	 * A conversation in the viewer's list. {@code status} mirrors the underlying match (ACTIVE or UNMATCHED).
	 * Unmatched conversations stay readable for their participants but cannot receive new messages.
	 */
	public record ConversationSummary(
			UUID conversationId,
			UUID matchId,
			String status,
			String lastMessagePreview,
			Instant lastMessageAt,
			long unreadCount) {
	}

	/** One page of conversations. {@code nextCursor} is null when no further results exist. */
	public record ConversationPage(List<ConversationSummary> items, String nextCursor) {
	}

	/** Marks a message as read by the viewer. Read state only moves forward. */
	public record ReadRequest(UUID messageId) {
	}

	public record ReadState(long unreadCount) {
	}
}
